/* Modal development store, using the existing character and catalog. */
window.ND_PROGRESSION=(()=>{
 const M=window.ND_PROGRESSION_MODEL,V=window.ND_CATALOG_V2;
 let state,section='attribute',pending=null,busy=false,rows=[],characterId,originalScroll=0,opening=false;
 const asset=(kind,id)=>'assets/progression/'+(kind==='perk'?'common/perk.png':kind==='attribute'?'attributes/':'skills/')+(kind==='perk'?'':id+'.png');
 function showError(message){const el=$('#progression-error');if(el)el.textContent=message;}
 function draw(){
 rows=M.options(card,D.catalog,state.history);
 const groups=[['attribute','Характеристики'],['skill','Навыки'],['perk','Перки и способности']];
 const count=k=>state.history.filter(x=>x.kind===k).length;
 $('#dialog').innerHTML=`<header class="progression-heading"><div><h2>Развитие персонажа</h2></div><div class="progression-header-controls"><div class="progression-balance"><img src="assets/progression/common/experience.png" alt=""><span>Доступно: <b>${card.experience} ОО</b></span></div><button id="progression-close" aria-label="Закрыть развитие персонажа" ${busy?'disabled':''}><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div></header><nav class="progression-tabs" aria-label="Виды улучшений">${groups.map(([k,n])=>`<button data-progression-tab="${k}" aria-pressed="${section===k}">${k==='perk'?'Перки':n}</button>`).join('')}</nav><p id="progression-error" role="alert"></p><div class="progression-columns">${groups.map(([kind,title])=>`<section class="progression-section ${section===kind?'is-selected':''}" aria-label="${title}"><header><h3>${title}</h3>${kind!=='perk'?`<small>Повышений за кампанию: ${count(kind)} / 2</small>`:''}</header><div class="progression-cards">${rows.filter(x=>x.kind===kind).map((x)=>`<article class="progression-card ${x.reasons.length?'is-unavailable':''}"><div class="progression-card-title"><span class="progression-icon"><img src="${asset(kind,x.id)}" alt=""></span><div><h4>${esc(x.name)}</h4>${kind==='perk'?`<small>${esc(x.item.subtype||x.item.type||'Перк')}</small>`:`<strong class="progression-values">${x.before} <span>→</span> ${x.after}</strong>`}</div></div>${kind==='perk'?`<p class="progression-description">${esc(x.item.description||x.item.rulesText||'Описание не задано')}</p><details><summary>Требования и правила</summary><p>${requirementsText(x)}</p>${x.item.rulesText!==x.item.description?`<p>${esc(x.item.rulesText||'')}</p>`:''}</details>`:''}<div class="progression-card-action"><b>${Number.isSafeInteger(x.cost)?x.cost+' ОО':'Цена не задана'}</b><button data-development="${rows.indexOf(x)}" ${busy||x.reasons.length?'disabled':''}>${kind==='perk'?'Приобрести':'Улучшить'}</button></div><p class="progression-reason">${x.reasons.map(esc).join(' · ')||'Доступно'}</p></article>`).join('')||'<p>В справочнике пока нет доступных перков.</p>'}</div></section>`).join('')}</div>${canManageStats()?'<div class="progression-admin"><button id="progression-restore">Восстановить старую покупку</button></div>':''}${pending?confirmation():''}`;
 $('#progression-close').onclick=close;
 document.querySelectorAll('[data-progression-tab]').forEach(b=>b.onclick=()=>{section=b.dataset.progressionTab;draw();});
 document.querySelectorAll('[data-development]').forEach(b=>b.onclick=()=>{pending={...rows[+b.dataset.development],operationId:crypto.randomUUID()};draw();$('#progression-confirm')?.focus();});
 if($('#progression-cancel'))$('#progression-cancel').onclick=()=>{if(!busy){pending=null;draw();}};
 if($('#progression-confirm'))$('#progression-confirm').onclick=purchase;
 if($('#progression-restore'))$('#progression-restore').onclick=restore;
 $('#dialog').onkeydown=e=>{if(e.key==='Tab'&&pending){const buttons=[...document.querySelectorAll('.progression-confirm button:not(:disabled)')];if(!buttons.length){e.preventDefault();return;}const first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};
 $('#dialog').oncancel=e=>{e.preventDefault();if(busy)return;if(pending){pending=null;draw();}else close();};
 }
 function requirementsText(x){const req=x.item?.requirements??[];return (Array.isArray(req)?req.map(r=>{const ids=r.kind==='attribute'?V.attributeIds:V.skillIds;return esc((M.names[r.kind]||[])[ids.indexOf(r.targetId)]||r.targetId)+' ≥ '+esc(r.minimum)+' (база)';}).join('<br>'):'Неформализованные требования')||esc(x.item?.requirementsText||x.item?.availability?.restrictions||'Дополнительные требования не заданы');}
 function confirmation(){const x=pending;return `<div class="progression-confirm-backdrop"><section class="progression-confirm" role="alertdialog" aria-modal="true" aria-labelledby="progression-confirm-title"><span class="eyebrow">ПОДТВЕРЖДЕНИЕ ПОКУПКИ</span><h3 id="progression-confirm-title">${esc(x.name)}</h3>${x.kind==='perk'?`<p>${esc(x.item.description||'')}</p><p>${requirementsText(x)}</p>`:`<p>Базовое значение: <b>${x.before} → ${x.after}</b></p><p>Бонусы снаряжения сохраняются</p>`}<dl><div><dt>Стоимость</dt><dd>${x.cost} ОО</dd></div><div><dt>Доступно</dt><dd>${card.experience} ОО</dd></div><div><dt>Останется</dt><dd>${card.experience-x.cost} ОО</dd></div></dl><p id="progression-purchase-error" role="alert"></p><div class="progression-confirm-actions"><button id="progression-cancel" ${busy?'disabled':''}>Отмена</button><button id="progression-confirm" class="yellow" ${busy?'disabled':''}>${busy?'Сохраняем…':'Подтвердить покупку'}</button></div></section></div>`;}
 async function flush(){clearTimeout(saveTimer);if(saving)throw Error('Карточка сохраняется. Подожди несколько секунд и повтори.');await save();if(dirty||saving||conflict)throw Error('Сначала синхронизируй карточку с облаком.');}
 async function open(perkId){
 if(opening||busy||!canEdit||!E.canSpendExperience(card))return;
 opening=true;
 try{if(!cloudRecord)throw Error('Для покупок сохрани персонажа в облаке.');await flush();if(card.equipmentVersion!==2){card=V.normalizeCharacter(card,D.catalog);changed();await flush();}
 characterId=cloudRecord.id;await loadCatalog();state=await C.progressionState(characterId);pending=null;section=perkId?'perk':'attribute';originalScroll=window.scrollY;
 modal('Развитие персонажа','');$('#dialog').classList.add('progression-dialog');document.body.classList.add('progression-open');$('#dialog').onclose=()=>{document.body.classList.remove('progression-open');$('#dialog').classList.remove('progression-dialog');$('#dialog').onclose=null;$('#dialog').onkeydown=null;window.scrollTo(0,originalScroll);};draw();
 if(perkId){const x=rows.find(x=>x.kind==='perk'&&x.id===perkId);if(x&&!x.reasons.length){pending={...x,operationId:crypto.randomUUID()};draw();}}
 }catch(e){notify(e.message);}finally{opening=false;}}
 async function purchase(){if(busy||!pending)return;busy=true;const x=pending;draw();try{await flush();if(!canEdit||cloudRecord?.id!==characterId)throw Error('Персонаж изменился. Открой магазин снова.');const result=await C.purchaseProgression(characterId,x.kind,x.id,x.operationId,cloudRecord.revision,x.cost);cloudRecord=result.character;card=E.validate(result.character.data,D);dirty=false;conflict=false;version++;state=result.state;localStorage.removeItem('nd-draft-'+C.user()?.id+'-'+characterId);setStatus(confirmedSyncStatus());pending=null;render();notify(result.replayed?'Покупка уже была сохранена':'Улучшение приобретено');}catch(e){const msg=e.message;busy=false;draw();$('#progression-purchase-error').textContent=msg;return;}finally{busy=false;}draw();}
 function close(){if(busy)return;pending=null;closeModal();}
 function restore(){
 if(!canManageStats())return;
 const choices=rows.filter(x=>x.kind!=='perk');
 $('#dialog').innerHTML=`<header class="progression-heading"><h2>Восстановление истории</h2><button id="restore-back">Назад</button></header><p>Только для старых покупок без истории. Опыт и базовые значения не изменятся. Запись займёт лимит текущей кампании.</p><form id="restore-development"><label>Улучшение<select name="target">${choices.map((x,i)=>`<option value="${i}">${esc(x.name)}</option>`).join('')}</select></label><label>Базовое значение до покупки<input name="before" type="number" min="0" step="1" required value="2"></label><button class="yellow">Добавить запись в историю</button></form><p id="progression-error" role="alert"></p>`;
 $('#restore-back').onclick=draw;$('#restore-development').onsubmit=async e=>{e.preventDefault();const f=e.target,x=choices[+f.elements.target.value],before=Number(f.elements.before.value);if(!confirm('Восстановить факт покупки «'+x.name+'»? Значения персонажа не изменятся.'))return;const button=f.querySelector('button');button.disabled=true;try{state=await C.restoreProgression(characterId,x.kind,x.id,before,before+1,x.cost,crypto.randomUUID());draw();}catch(err){showError(err.message);button.disabled=false;}};
 }
 return {open};
})();

